const OPERATIONS = ['add', 'subtract', 'multiply', 'divide'];

export async function listTools() {
  return [{
    name: 'calculate',
    description: 'Perform a basic arithmetic calculation on two numbers.',
    inputSchema: {
      type: 'object',
      properties: {
        a: { type: 'number', description: 'The first operand.' },
        b: { type: 'number', description: 'The second operand.' },
        operation: { type: 'string', enum: OPERATIONS, description: 'The arithmetic operation to perform.' }
      },
      required: ['a', 'b', 'operation'],
      additionalProperties: false
    }
  }];
}

function isNumber(v) {
  return typeof v === 'number' && Number.isFinite(v);
}

export async function callTool(name, args) {
  if (name !== 'calculate') {
    throw new Error(`Unknown tool: ${name}`);
  }
  const { a, b, operation } = args ?? {};
  const allowed = new Set(['a', 'b', 'operation']);
  for (const key of Object.keys(args ?? {})) {
    if (!allowed.has(key)) {
      throw new Error(`Unexpected field: ${key}`);
    }
  }
  if (a === undefined || b === undefined || operation === undefined) {
    throw new Error('Missing required field(s): a, b, operation');
  }
  if (!isNumber(a)) {
    throw new Error('Field "a" must be a finite number');
  }
  if (!isNumber(b)) {
    throw new Error('Field "b" must be a finite number');
  }
  if (!OPERATIONS.includes(operation)) {
    throw new Error(`Unsupported operation: ${operation}`);
  }
  let result;
  switch (operation) {
    case 'add': result = a + b; break;
    case 'subtract': result = a - b; break;
    case 'multiply': result = a * b; break;
    case 'divide':
      if (b === 0) {
        throw new Error('Division by zero is not allowed');
      }
      result = a / b;
      break;
  }
  return { content: [{ type: 'text', text: String(result) }] };
}
